const r = msg.payload;

// /status del detector → objeto con fsm_state
if (r && typeof r.fsm_state === "string") {
    // Hay prenda mientras la FSM está en "en_prenda"
    const hayPrenda = (r.fsm_state === "en_prenda") ? 1 : 0;

    // Publica solo cuando CAMBIA (evita repetir cada 2s)
    const prev = flow.get("gpio4_estado");
    if (prev === hayPrenda) return null;
    flow.set("gpio4_estado", hayPrenda);

    // 0→1 = entra prenda ; 1→0 = sale prenda (= 1 corte)
    return { topic: "gpio/4", payload: hayPrenda };
}

return null;

// Estado de la FSM del detector (presencia)
msg.url = "http://host.docker.internal:8001/status";
return msg;

const r = msg.payload;
const DEV = { uuid: global.get("dev_id") || "SIN_ID", name: global.get("dev_name") || "SIN_NOMBRE" };
const now = Date.now();
const CONFIRMS = 3;   // lecturas seguidas para confirmar (anti-flapping)

const errado = !!msg.error
            || !!(r && (r.code === "ECONNREFUSED" || r.name === "RequestError"));
const detectorOk = !errado;
const camOk = detectorOk && !!(r && r.camera === true);

const CAT = [
  { id: 7, name: "DETECTOR NO RESPONDE", activa: !detectorOk,          value: 0, unit: "" },
  { id: 1, name: "CAMARA DESCONECTADA",  activa: detectorOk && !camOk, value: 0, unit: "" },
];

const salida = [];
for (const a of CAT) {
  const sKey = "alarma_" + a.id;        // estado publicado
  const cKey = "alarma_cnt_" + a.id;    // contador anti-flapping
  const prev = flow.get(sKey) || 0;
  const cur  = a.activa ? 1 : 0;

  if (cur === prev) { flow.set(cKey, 0); continue; }       // sin cambio
  const cnt = (flow.get(cKey) || 0) + 1;
  if (cnt < CONFIRMS) { flow.set(cKey, cnt); continue; }   // aún no confirma

  flow.set(cKey, 0);
  flow.set(sKey, cur);
  salida.push({ topic: "alarms", payload: {
    device_uuid: DEV.uuid, device_name: DEV.name,
    alarm_id: a.id, alarm_name: a.name,
    state: cur, value: a.value, unit: a.unit, timestamp: now
  }});
}
return [salida];

