const estadoActual = datos.fsm_state;
const hayMovimiento = datos.presence_motion;
const limiteMicroparadaS = Number(datos.micro_stop_max_s);

// -----------------------------------------------------
// Función para leer variables globales de forma segura
// -----------------------------------------------------

function leerGlobal(nombre) {
    const valor = Number(global.get(nombre));

    if (!Number.isFinite(valor) || valor < 0) {
        return 0;
    }

    return valor;
}

// -----------------------------------------------------
// Calcular segundos transcurridos entre consultas
// -----------------------------------------------------

const ultimoTiempo = context.get("prod_ultimo_tiempo_ms");

let segundos = 0;

if (typeof ultimoTiempo === "number") {
    segundos = Math.floor((ahora - ultimoTiempo) / 1000);

    // Evita acumular un tiempo falso si Node-RED estuvo detenido
    if (primeraMuestraLista || segundos < 0 || segundos > 15) {
        segundos = 0;
    }
}

context.set("prod_ultimo_tiempo_ms", ahora);

// -----------------------------------------------------
// Leer acumuladores globales
