let tiempoDisponible =
    leerGlobal("L1_t_disponible");

let tiempoMicroparada =
    leerGlobal("L1_t_microparada");

let tiempoParadaNoAsignada =
    leerGlobal("L1_t_parada_no_asignada");

let conteo =
    leerGlobal("L1_conteo_1");

