    context.get("prod_estado_anterior");

// -----------------------------------------------------
// 1. TIEMPO DISPONIBLE
// -----------------------------------------------------

// Aumenta mientras el detector entregue estados válidos
tiempoDisponible += segundos;

// -----------------------------------------------------
// 2. CONTEO DE PRODUCCIÓN
